\draw (-1.665, 1.337) -- (-1.452, 1.204) -- (-1.585, 0.991);
\draw (1.665, 1.337) -- (1.452, 1.204) -- (1.585, 0.991);
\end{tikzpicture}}\end{center} [[br]] \textbf{Vẽ hình, GT -- KL (0,25đ)} [[br]] Vẽ hình đúng theo yêu cầu bài toán. [[br]] Giả thiết và kết luận của bài toán: [[br]] $\begin{array}{l|l} \text{GT} & \Delta ABC,\ AB = AC \\ & AD\text{ là tia phân giác của }\widehat{A},\ D \in BC \\ & \text{b) } DE \perp AB\ (E \in AB),\ DF \perp AC\ (F \in AC) \\ & \text{c) } I\text{ là trung điểm của } EF \\ \hline \text{KL} & \text{a) } \Delta ABD = \Delta ACD \\ & \text{b) } DE = DF \\ & \text{c) } 3\text{ điểm } A, I, D\text{ thẳng hàng} \end{array}$ \hfill \textit{(0,25đ)} [[br]] \textbf{a) (0,5đ)} [[br]] Xét $\Delta ABD$ và $\Delta ACD$ có: [[br]] -- $AB = AC$ (giả thiết); [[br]] -- $\widehat{BAD} = \widehat{CAD}$ ($AD$ là tia phân giác của $\widehat{BAC}$); [[br]] -- $AD$ là cạnh chung. [[br]] Do đó $\Delta ABD = \Delta ACD$ (c.g.c). \hfill \textit{(0,5đ)} [[br]] \textbf{b) (0,5đ)} [[br]] Vì $DE \perp AB$ ($E \in AB$) nên $\widehat{DEA} = 90^\circ$. [[br]] Vì $DF \perp AC$ ($F \in AC$) nên $\widehat{DFA} = 90^\circ$. \hfill \textit{(0,25đ)} [[br]] Xét $\Delta ADE$ và $\Delta ADF$ có: [[br]] -- $\widehat{DEA} = \widehat{DFA} = 90^\circ$; [[br]] -- $AD$ là cạnh chung; [[br]] -- $\widehat{EAD} = \widehat{FAD}$ (do $AD$ là tia phân giác của $\widehat{BAC}$). [[br]] Suy ra $\Delta ADE = \Delta ADF$ (cạnh huyền -- góc nhọn). [[br]] Do đó $DE = DF$ (hai cạnh tương ứng). \hfill \textit{(0,25đ)} [[br]] \textbf{c) (0,25đ)} [[br]] Từ $\Delta ADE = \Delta ADF$ (chứng minh ở câu b) suy ra $AE = AF$ (hai cạnh tương ứng). [[br]] Xét $\Delta AIE$ và $\Delta AIF$ có: [[br]] -- $AE = AF$ (chứng minh trên); [[br]] -- $IE = IF$ ($I$ là trung điểm của $EF$); [[br]] -- $AI$ là cạnh chung. [[br]] Suy ra $\Delta AIE = \Delta AIF$ (c.c.c). [[br]] Do đó $\widehat{EAI} = \widehat{FAI}$ (hai góc tương ứng). [[br]] Vì $\widehat{EAI} = \widehat{FAI}$ nên $AI$ là tia phân giác của $\widehat{BAC}$. [[br]] Mà $AD$ cũng là tia phân giác của $\widehat{BAC}$ (giả thiết). [[br]] Do đó hai tia $AI$ và $AD$ trùng nhau, hay ba điểm $A, I, D$ thẳng hàng. \hfill \textit{(0,25đ)}
